/// <summary>
/// This Class Generate Number Sequence For TMS Shipment Order Identifier
/// </summary>
public class METShipmentOrderIDNumSeq extends NumberSeqApplicationModule
{

    
}

Method.Source:
        /// <summary>
        /// In This Function we will  set some important Atribute for parameter of Number Sequence
        /// </summary>
        protected void loadModule()
        {
            NumberSeqDatatype datatype = NumberSeqDatatype::construct();
            datatype.parmDatatypeId(extendedTypeNum(METTMSShipmentOrderIdentifier));

            datatype.parmReferenceHelp(literalStr("@MET:METTMSShipmentOrderIdentifier"));
            datatype.parmWizardIsContinuous(false);
            datatype.parmWizardfetchAheadQty(10);
            datatype.parmWizardIsManual(NoYes::No);
            datatype.parmWizardIsChangeDownAllowed(NoYes::No);
            datatype.parmWizardIsChangeUpAllowed(NoYes::No);
            datatype.parmSortField(1);

            datatype.addParameterType(NumberSeqParameterType::DataArea,true,false);
            this.create(datatype);
        }

/// <summary>
/// This Will create Number Sequence in Warehouse Management You can change according to your need, if needed
/// </summary>
/// <returns> WHS</returns>
public NumberSeqModule numberSeqModule()
{
    return NumberSeqModule::WHS;
}

     /// <summary>
     /// This subscribe of Global Number Sequence Class
     /// </summary>
     /// <param name = "numberSeqModuleNameMap">NumberSeqGlobal</param>
     [SubscribesTo(classstr(NumberSeqGlobal),delegateStr(NumberSeqGlobal,buildModulesMapDelegate))]

     static void buildModulesMapSubscribes(Map numberSeqModuleNameMap)
     {
         NumberSeqGlobal::addModuleToMap(classNum(METShipmentOrderIDNumSeq),numberSeqModuleNameMap);
     }
